const cmds = [
  " \"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" check",
  " \"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" response --help",
  "cat /Users/johnlee/.local/state/stamped-ai-research-next/stamped-judge-o9b820ok/skills/stamped-conventions/SKILL.md",
  "date -u +%F"
];
const rs = await Promise.allSettled(cmds.map(cmd=>tools.exec_command({cmd:cmd.trim(),yield_time_ms:10000,max_output_tokens:3500})));
for (let i=0;i<rs.length;i++){text(`--- ${i+1} ---`);text(rs[i].status==="fulfilled"?rs[i].value.output:String(rs[i].reason));}

