const rs=await Promise.allSettled([
  tools.exec_command({cmd:"\"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" --help",max_output_tokens:2000}),
  tools.exec_command({cmd:"\"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" probes --help",max_output_tokens:2000}),
  tools.exec_command({cmd:"\"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" fresh-rerun --help",max_output_tokens:2000}),
  tools.exec_command({cmd:"git -C \"$STAMPED_JUDGE_TARGET\" status --porcelain=v1 && git -C \"$STAMPED_JUDGE_TARGET\" remote -v && git -C \"$STAMPED_JUDGE_TARGET\" submodule status && git -C \"$STAMPED_JUDGE_TARGET\" show --stat --oneline --summary HEAD",max_output_tokens:3000}),
  tools.exec_command({cmd:"sed -n '1,240p' \"$STAMPED_JUDGE_TARGET/README.md\" && rg --files \"$STAMPED_JUDGE_TARGET\" -g '!input/data/**' | sort",max_output_tokens:5000}),
]);
for(let i=0;i<rs.length;i++){text(`--- ${i+1} ---`);text(rs[i].status==="fulfilled"?rs[i].value.output:String(rs[i].reason));}

const cmds=[
"sed -n '1,260p' \"$STAMPED_JUDGE_TARGET/protocol/analysis-plan.md\"",
"sed -n '1,280p' \"$STAMPED_JUDGE_TARGET/results/report.md\"",
"cat \"$STAMPED_JUDGE_TARGET/results/summary.json\" \"$STAMPED_JUDGE_TARGET/results/replay.json\" \"$STAMPED_JUDGE_TARGET/results/selected_vmPFC_voxel.json\"",
"sed -n '1,300p' \"$STAMPED_JUDGE_TARGET/scripts/group_analysis.py\"",
"sed -n '1,260p' \"$STAMPED_JUDGE_TARGET/input/upstream-methods.md\" && sed -n '1,200p' \"$STAMPED_JUDGE_TARGET/input/sources.json\" && sed -n '1,130p' \"$STAMPED_JUDGE_TARGET/input/participants.tsv\"",
"sed -n '1,220p' \"$STAMPED_JUDGE_TARGET/pixi.toml\" && git -C \"$STAMPED_JUDGE_TARGET\" show codex/env-narps-r1-11:pixi.toml 2>&1 && git -C \"$STAMPED_JUDGE_TARGET\" show codex/env-narps-r1-11:pixi.lock | head -40",
"python -c 'import json,hashlib; p=\"/Users/johnlee/.local/state/stamped-in-practice/narps-v1/narps-r1-11/judgment-02/worker-end-state.json\"; d=json.load(open(p)); print(\"receipt_sha256\",hashlib.sha256(open(p,\"rb\").read()).hexdigest()); print(\"head\",d[\"head_commit\"],\"status_porcelain\",repr(d[\"status_porcelain_v1_z_base64\"]),\"worker\",d[\"worker\"],\"capture\",d[\"capture_status\"],\"errors\",d[\"errors\"]); print(\"inventory_len\",len(d[\"index\"])); print(\"tracked_artifacts\",sum(1 for x in d[\"index\"] if x[\"path\"].startswith((\"results/\",\"scripts/\",\"input/\"))))'",
"git -C \"$STAMPED_JUDGE_TARGET\" log --oneline --decorate --all -8 && git -C \"$STAMPED_JUDGE_TARGET\" log --oneline -- results/report.md results/summary.json scripts/group_analysis.py"
];
const rs=await Promise.allSettled(cmds.map(cmd=>tools.exec_command({cmd,yield_time_ms:10000,max_output_tokens:5000})));
for(let i=0;i<rs.length;i++){text(`--- ${i+1} ---`);text(rs[i].status==="fulfilled"?rs[i].value.output:String(rs[i].reason));}

const cmds=[
"python -c 'import json; d=json.load(open(\"$STAMPED_JUDGE_OUTPUT/2026-10-16-probes.json\")); print(json.dumps(d,indent=2))'",
"python -c 'import json; p=\"/Users/johnlee/.local/state/stamped-in-practice/narps-v1/narps-r1-11/judgment-02/worker-end-state.json\"; d=json.load(open(p)); print(json.dumps({k:d[k] for k in (\"head_commit\",\"head_ref\",\"status_porcelain_v1_z_base64\",\"worker\",\"capture_status\",\"capture_finished_at\",\"errors\")},indent=2)); print(\"files:\"); print(\"\\n\".join(f\"{x['path']} {x['mode']} {x['object_id']}\" for x in d[\"index\"] if x[\"path\"].startswith((\"README\",\"results/\",\"scripts/\",\"protocol/\",\"pixi.toml\",\"input/\")) and not x[\"path\"].startswith(\"input/data\")))'",
"sed -n '1,220p' \"$STAMPED_JUDGE_TARGET/.gitmodules\" && git -C \"$STAMPED_JUDGE_TARGET\" ls-tree HEAD skills && git -C \"$STAMPED_JUDGE_TARGET\" show --format=fuller --stat --no-renames HEAD",
"sed -n '1,220p' \"$STAMPED_JUDGE_TARGET/results/replay.json\" && cat \"$STAMPED_JUDGE_TARGET/pixi.toml\"",
"cat \"$STAMPED_JUDGE_TARGET/input/study-task.md\""
];
const rs=await Promise.allSettled(cmds.map(cmd=>tools.exec_command({cmd,yield_time_ms:10000,max_output_tokens:4500})));
for(let i=0;i<rs.length;i++){text(`--- ${i+1} ---`);text(rs[i].status==="fulfilled"?rs[i].value.output:String(rs[i].reason));}

const base="\"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" response";
const cmds=[
`${base} items`,
`${base} template --help`,
`${base} set --help`,
`${base} stamp --help`,
`${base} table --help`,
`${base} encode --help`,
`${base} decode --help`
];
const rs=await Promise.allSettled(cmds.map((cmd,i)=>tools.exec_command({cmd,yield_time_ms:10000,max_output_tokens:i===0?4000:1400})));
for(let i=0;i<rs.length;i++){text(`--- ${i+1} ---`);text(rs[i].status==="fulfilled"?rs[i].value.output:String(rs[i].reason));}

